red":{"@type":"Service","name":"Commercial & HOA Appraisal","url":"https://ohioinsuranceappraiser.com/appraisal-practice/commercial-hoa-appraisal/"}},{"@type":"Offer","itemOffered":{"@type":"Service","name":"Hail & Roof Appraisal","url":"https://ohioinsuranceappraiser.com/appraisal-practice/hail-roof-appraisal/"}},{"@type":"Offer","itemOffered":{"@type":"Service","name":"Tornado & Windstorm Appraisal","url":"https://ohioinsuranceappraiser.com/appraisal-practice/tornado-windstorm-appraisal/"}},{"@type":"Offer","itemOffered":{"@type":"Service","name":"Derecho & Hurricane Remnant Appraisal","url":"https://ohioinsuranceappraiser.com/appraisal-practice/derecho-remnant-storm-appraisal/"}},{"@type":"Offer","itemOffered":{"@type":"Service","name":"Water Damage Appraisal","url":"https://ohioinsuranceappraiser.com/appraisal-practice/water-damage-appraisal/"}},{"@type":"Offer","itemOffered":{"@type":"Service","name":"Fire & Smoke Appraisal","url":"https://ohioinsuranceappraiser.com/appraisal-practice/fire-smoke-appraisal/"}},{"@type":"Offer","itemOffered":{"@type":"Service","name":"Ice Dam & Frozen Pipe Appraisal","url":"https://ohioinsuranceappraiser.com/appraisal-practice/ice-dam-frozen-pipe-appraisal/"}},{"@type":"Offer","itemOffered":{"@type":"Service","name":"Estimate Audit","url":"https://ohioinsuranceappraiser.com/appraisal-practice/estimate-audit/"}},{"@type":"Offer","itemOffered":{"@type":"Service","name":"Neutral Umpire Services","url":"https://ohioinsuranceappraiser.com/appraisal-practice/neutral-umpire-services/"}}]},"knowsAbout":["Insurance appraisal","Appraisal clause","Umpire","Hail damage","Wind and tornado damage","Ice dams","Sewer backup","Xactimate estimating"],"openingHoursSpecification":[{"@type":"OpeningHoursSpecification","dayOfWeek":["Monday","Tuesday","Wednesday","Thursday","Friday"],"opens":"08:00","closes":"18:00"}]},{"@type":"WebSite","@id":"https://ohioinsuranceappraiser.com/#website","url":"https://ohioinsuranceappraiser.com/","name":"Ohio Insurance Appraiser","publisher":{"@id":"https://ohioinsuranceappraiser.com/#business"},"inLanguage":"en-US"},{"@type":"WebPage","@id":"https://ohioinsuranceappraiser.com/appraisal-lexicon/#webpage","url":"https://ohioinsuranceappraiser.com/appraisal-lexicon/","name":"Insurance Appraisal Glossary | Claim Terms Defined","description":"Insurance appraisal glossary with 43 searchable claim terms: ACV, RCV, holdback, umpire, award, percentage deductible, backup endorsement and more.","inLanguage":"en-US","isPartOf":{"@id":"https://ohioinsuranceappraiser.com/#website"},"about":{"@id":"https://ohioinsuranceappraiser.com/#business"},"publisher":{"@id":"https://ohioinsuranceappraiser.com/#business"},"dateModified":"2026-11-12","primaryImageOfPage":{"@type":"ImageObject","@id":"https://ohioinsuranceappraiser.com/appraisal-lexicon/#primaryimage","url":"https://ohioinsuranceappraiser.com/assets/img/photos/paperwork.webp","width":1024,"height":512,"caption":"Hand signing a document at a table with coffee and notes"},"breadcrumb":{"@id":"https://ohioinsuranceappraiser.com/appraisal-lexicon/#breadcrumb"},"mainEntity":{"@id":"https://ohioinsuranceappraiser.com/appraisal-lexicon/#definedtermset"}},{"@type":"BreadcrumbList","itemListElement":[{"@type":"ListItem","position":1,"name":"Home","item":"https://ohioinsuranceappraiser.com/"},{"@type":"ListItem","position":2,"name":"Appraisal lexicon","item":"https://ohioinsuranceappraiser.com/appraisal-lexicon/"}],"@id":"https://ohioinsuranceappraiser.com/appraisal-lexicon/#breadcrumb"},{"@type":"DefinedTermSet","name":"Ohio insurance appraisal lexicon","url":"https://ohioinsuranceappraiser.com/appraisal-lexicon/","hasDefinedTerm":[{"@type":"DefinedTerm","name":"Actual Cash Value (ACV)","description":"What damaged property is worth at the time of loss, usually figured as replacement cost minus depreciation. Many Ohio policies pay ACV first and the balance after repairs.","inDefinedTermSet":{"@id":"https://ohioinsuranceappraiser.com/appraisal-lexicon/#definedtermset"}},{"@type":"DefinedTerm","name":"Additional Living Expense (ALE)","description":"Coverage for the extra cost of living elsewhere while your home is unlivable after a covered loss, such as rent, hotel bills or added mileage.","inDefinedTermSet":{"@id":"https://ohioinsuranceappraiser.com/appraisal-lexicon/#definedtermset"}},{"@type":"DefinedTerm","name":"Appraisal Clause","description":"The policy provision that lets either party demand a panel of two appraisers and an umpire to set the amount of loss when the two sides disagree on price.","inDefinedTermSet":{"@id":"https://ohioinsuranceappraiser.com/appraisal-lexicon/#definedtermset"}},{"@type":"DefinedTerm","name":"Award","description":"The written decision that fixes the amount of loss. An award signed by any two of the three panel members is generally binding on the amount.","inDefinedTermSet":{"@id":"https://ohioinsuranceappraiser.com/appraisal-lexicon/#definedtermset"}},{"@type":"DefinedTerm","name":"Cosmetic Damage Exclusion","description":"An endorsement on some policies that excludes dents or marks, often on metal roofing or siding, that change appearance but not function.","inDefinedTermSet":{"@id":"https://ohioinsuranceappraiser.com/appraisal-lexicon/#definedtermset"}},{"@type":"DefinedTerm","name":"Coverage A (Dwelling)","description":"The part of a homeowners policy that insures the house itself and attached structures such as an attached garage or porch.","inDefinedTermSet":{"@id":"https://ohioinsuranceappraiser.com/appraisal-lexicon/#definedtermset"}},{"@type":"DefinedTerm","name":"Coverage B (Other Structures)","description":"Coverage for detached structures on the property, such as a detached garage, shed or fence, usually set as a percentage of Coverage A.","inDefinedTermSet":{"@id":"https://ohioinsuranceappraiser.com/appraisal-lexicon/#definedtermset"}},{"@type":"DefinedTerm","name":"Coverage C (Personal Property)","description":"Coverage for belongings like furniture, clothing and electronics, whether damaged at home or, within limits, elsewhere.","inDefinedTermSet":{"@id":"https://ohioinsuranceappraiser.com/appraisal-lexicon/#definedtermset"}},{"@type":"DefinedTerm","name":"Coverage D (Loss of Use)","description":"Coverage for additional living expenses or lost rental income when a covered loss makes the home unfit to live in.","inDefinedTermSet":{"@id":"https://ohioinsuranceappraiser.com/appraisal-lexicon/#definedtermset"}},{"@type":"DefinedTerm","name":"Declarations Page","description":"The summary page of a policy listing the insured, property address, coverage limits, deductibles and endorsements.","inDefinedTermSet":{"@id":"https://ohioinsuranceappraiser.com/appraisal-lexicon/#definedtermset"}},{"@type":"DefinedTerm","name":"Deductible","description":"The share of a covered loss you pay before the insurer pays. It is subtracted from the claim payment rather than paid to anyone.","inDefinedTermSet":{"@id":"https://ohioinsuranceappraiser.com/appraisal-lexicon/#definedtermset"}},{"@type":"DefinedTerm","name":"Depreciation","description":"The reduction in value for age, wear and condition. In a claim it is the difference between replacement cost and actual cash value.","inDefinedTermSet":{"@id":"https://ohioinsuranceappraiser.com/appraisal-lexicon/#definedtermset"}},{"@type":"DefinedTerm","name":"Derecho","description":"A long-lived, widespread windstorm produced by a line of fast-moving thunderstorms, like the June 29, 2012 event that swept central and southern Ohio.","inDefinedTermSet":{"@id":"https://ohioinsuranceappraiser.com/appraisal-lexicon/#definedtermset"}},{"@type":"DefinedTerm","name":"Functional Damage","description":"Damage that impairs how a component works or shortens its life, such as hail that fractures shingle mat or cracks slate.","inDefinedTermSet":{"@id":"https://ohioinsuranceappraiser.com/appraisal-lexicon/#definedtermset"}},{"@type":"DefinedTerm","name":"Holdback","description":"The recoverable depreciation an insurer withholds from the first payment until repairs are completed and documented.","inDefinedTermSet":{"@id":"https://ohioinsuranceappraiser.com/appraisal-lexicon/#definedtermset"}},{"@type":"DefinedTerm","name":"Ice Dam","description":"A ridge of ice at a roof edge that traps melting snow, letting water back up under shingles and into walls and ceilings.","inDefinedTermSet":{"@id":"https://ohioinsuranceappraiser.com/appraisal-lexicon/#definedtermset"}},{"@type":"DefinedTerm","name":"Impartial Appraiser","description":"An appraiser with no financial stake in the outcome. Many policies require each party’s appraiser to be impartial, independent or disinterested.","inDefinedTermSet":{"@id":"https://ohioinsuranceappraiser.com/appraisal-lexicon/#definedtermset"}},{"@type":"DefinedTerm","name":"Line Item","description":"A single entry in a repair estimate, such as removing and replacing a square of shingles, with its quantity, unit price and total.","inDefinedTermSet":{"@id":"https://ohioinsuranceappraiser.com/appraisal-lexicon/#definedtermset"}},{"@type":"DefinedTerm","name":"Matching","description":"The question of whether undamaged materials must be replaced so repairs blend with what remains, common with roofing, siding and flooring.","inDefinedTermSet":{"@id":"https://ohioinsuranceappraiser.com/appraisal-lexicon/#definedtermset"}},{"@type":"DefinedTerm","name":"Mitigation","description":"Reasonable steps to prevent further damage after a loss, like tarping a roof or extracting water. Most policies require it.","inDefinedTermSet":{"@id":"https://ohioinsuranceappraiser.com/appraisal-lexicon/#definedtermset"}},{"@type":"DefinedTerm","name":"Mortgagee Clause","description":"The policy provision that protects the lender’s interest and is why claim checks are often made out to both the owner and the mortgage company.","inDefinedTermSet":{"@id":"https://ohioinsuranceappraiser.com/appraisal-lexicon/#definedtermset"}},{"@type":"DefinedTerm","name":"Named Peril","description":"A policy approach that covers only the causes of loss specifically listed, such as fire, lightning or windstorm.","inDefinedTermSet":{"@id":"https://ohioinsuranceappraiser.com/appraisal-lexicon/#definedtermset"}},{"@type":"DefinedTerm","name":"NFIP","description":"The National Flood Insurance Program, the federal program that writes most flood policies. Standard Ohio homeowners policies exclude flood.","inDefinedTermSet":{"@id":"https://ohioinsuranceappraiser.com/appraisal-lexicon/#definedtermset"}},{"@type":"DefinedTerm","name":"ODI","description":"The Ohio Department of Insurance, the state agency that licenses insurers and enforces claim-handling rules.","inDefinedTermSet":{"@id":"https://ohioinsuranceappraiser.com/appraisal-lexicon/#definedtermset"}},{"@type":"DefinedTerm","name":"Ohio FAIR Plan","description":"The Ohio FAIR Plan Underwriting Association, the insurer of last resort for property owners who cannot get coverage in the voluntary market.","inDefinedTermSet":{"@id":"https://ohioinsuranceappraiser.com/appraisal-lexicon/#definedtermset"}},{"@type":"DefinedTerm","name":"Open Peril","description":"A policy approach that covers any cause of physical loss unless it is specifically excluded. Most Ohio homeowners policies insure the dwelling this way.","inDefinedTermSet":{"@id":"https://ohioinsuranceappraiser.com/appraisal-lexicon/#definedtermset"}},{"@type":"DefinedTerm","name":"Ordinance or Law","description":"Coverage for the added cost of bringing repaired property up to current building codes, usually capped at a percentage of the dwelling limit.","inDefinedTermSet":{"@id":"https://ohioinsuranceappraiser.com/appraisal-lexicon/#definedtermset"}},{"@type":"DefinedTerm","name":"Overhead and Profit (O&P)","description":"The general contractor’s charge for managing a job with several trades, often figured as a percentage of the repair estimate.","inDefinedTermSet":{"@id":"https://ohioinsuranceappraiser.com/appraisal-lexicon/#definedtermset"}},{"@type":"DefinedTerm","name":"Percentage Deductible","description":"A deductible set as a percentage of the dwelling limit, often 1%–5% for wind or hail on some Ohio policies, rather than a flat dollar amount.","inDefinedTermSet":{"@id":"https://ohioinsuranceappraiser.com/appraisal-lexicon/#definedtermset"}},{"@type":"DefinedTerm","name":"Pitch","description":"The steepness of a roof, written as inches of rise per 12 inches of run. Steeper roofs cost more to repair and may need extra safety labor.","inDefinedTermSet":{"@id":"https://ohioinsuranceappraiser.com/appraisal-lexicon/#definedtermset"}},{"@type":"DefinedTerm","name":"Proof of Loss","description":"A sworn statement of the amount claimed that some policies require within a set time, often on request from the insurer.","inDefinedTermSet":{"@id":"https://ohioinsuranceappraiser.com/appraisal-lexicon/#definedtermset"}},{"@type":"DefinedTerm","name":"Recoverable Depreciation","description":"Depreciation the insurer will pay once repairs or replacement are finished, under a replacement cost policy.","inDefinedTermSet":{"@id":"https://ohioinsuranceappraiser.com/appraisal-lexicon/#definedtermset"}},{"@type":"DefinedTerm","name":"Replacement Cost Value (RCV)","description":"The cost to repair or replace damaged property with materials of like kind and quality, without a deduction for depreciation.","inDefinedTermSet":{"@id":"https://ohioinsuranceappraiser.com/appraisal-lexicon/#definedtermset"}},{"@type":"DefinedTerm","name":"Reservation of Rights","description":"A letter in which the insurer handles a claim while saying it may later deny coverage on stated grounds.","inDefinedTermSet":{"@id":"https://ohioinsuranceappraiser.com/appraisal-lexicon/#definedtermset"}},{"@type":"DefinedTerm","name":"Scope of Loss","description":"The full list of damaged items and the repairs needed to restore them, which drives the size of every estimate.","inDefinedTermSet":{"@id":"https://ohioinsuranceappraiser.com/appraisal-lexicon/#definedtermset"}},{"@type":"DefinedTerm","name":"Sewer and Drain Backup Endorsement","description":"An add-on that covers water backing up through drains or a failed sump pump, usually with its own sublimit. Without it, most Ohio policies exclude this water.","inDefinedTermSet":{"@id":"https://ohioinsuranceappraiser.com/appraisal-lexicon/#definedtermset"}},{"@type":"DefinedTerm","name":"Square (Roofing)","description":"A unit of roof area equal to 100 square feet, used to measure and price roofing work.","inDefinedTermSet":{"@id":"https://ohioinsuranceappraiser.com/appraisal-lexicon/#definedtermset"}},{"@type":"DefinedTerm","name":"Suit Limitation","description":"A policy condition setting how long you have to file a lawsuit over a claim, often one year from the date of loss in Ohio policies.","inDefinedTermSet":{"@id":"https://ohioinsuranceappraiser.com/appraisal-lexicon/#definedtermset"}},{"@type":"DefinedTerm","name":"Supplement","description":"A request to add items or costs to an insurer’s estimate, often after hidden damage turns up during repairs.","inDefinedTermSet":{"@id":"https://ohioinsuranceappraiser.com/appraisal-lexicon/#definedtermset"}},{"@type":"DefinedTerm","name":"Test Square","description":"A 10-by-10-foot area marked on a roof slope where an inspector counts hail hits to judge whether the slope is damaged.","inDefinedTermSet":{"@id":"https://ohioinsuranceappraiser.com/appraisal-lexicon/#definedtermset"}},{"@type":"DefinedTerm","name":"Umpire","description":"The neutral third member of an appraisal panel who decides items the two party appraisers cannot agree on.","inDefinedTermSet":{"@id":"https://ohioinsuranceappraiser.com/appraisal-lexicon/#definedtermset"}},{"@type":"DefinedTerm","name":"Umpire Selection","description":"The process of the two appraisers agreeing on an umpire, or, if they cannot, asking a court in the county of the loss to appoint one.","inDefinedTermSet":{"@id":"https://ohioinsuranceappraiser.com/appraisal-lexicon/#definedtermset"}},{"@type":"DefinedTerm","name":"Xactimate","description":"Estimating software used by most insurers and many contractors to price repairs from regional unit-cost databases.","inDefinedTermSet":{"@id":"https://ohioinsuranceappraiser.com/appraisal-lexicon/#definedtermset"}}],"@id":"https://ohioinsuranceappraiser.com/appraisal-lexicon/#definedtermset"}]}</script>
</head>
